function sanitizeWord(raw: string): string {
  // Strip any accidental non-alpha characters (e.g. digits from OCR/copy)
  return raw.toUpperCase().replace(/[^A-Z]/g, '');
}

const VOWELS = new Set(['A', 'E', 'I', 'O', 'U', 'Y']);

function hasVowel(word: string): boolean {
  for (let i = 0; i < word.length; i++) {
    if (VOWELS.has(word[i])) return true;
  }
  return false;
}

/**
 * Generates standard English inflections (plurals, past tense, comparatives,
 * superlatives, gerunds, adverbs) from known base words so players can freely
 * guess valid 5-8 letter inflected forms without getting "NOT IN DICT".
 */
function generateInflections(baseWords: Iterable<string>): Set<string> {
  const inflected = new Set<string>();

  for (const raw of baseWords) {
    const w = sanitizeWord(raw);
    if (w.length < 3 || w.length > 8 || !hasVowel(w)) continue;
    inflected.add(w);

    const last = w[w.length - 1];
    const prev = w[w.length - 2] || '';
    const lastTwo = w.slice(-2);

    // 1. Plurals / 3rd-person singular (+S, +ES, -Y -> -IES)
    if (last === 'Y' && !VOWELS.has(prev)) {
      inflected.add(w.slice(0, -1) + 'IES');
      inflected.add(w.slice(0, -1) + 'IED');
      inflected.add(w.slice(0, -1) + 'IER');
      inflected.add(w.slice(0, -1) + 'IEST');
      inflected.add(w.slice(0, -1) + 'ILY');
    } else if (
      last === 'S' ||
      last === 'X' ||
      last === 'Z' ||
      lastTwo === 'CH' ||
      lastTwo === 'SH'
    ) {
      inflected.add(w + 'ES');
    } else {
      inflected.add(w + 'S');
    }

    // 2. Words ending in silent E (-E -> +D, +R, +RS, +ST, -E + ING)
    if (last === 'E') {
      inflected.add(w + 'D');
      inflected.add(w + 'R');
      inflected.add(w + 'RS');
      inflected.add(w + 'ST');
      if (prev !== 'E' && prev !== 'I' && prev !== 'Y') {
        inflected.add(w.slice(0, -1) + 'ING');
      }
    } else {
      // Regular +ED, +ING, +ER, +ERS, +EST, +LY
      inflected.add(w + 'ED');
      inflected.add(w + 'ING');
      inflected.add(w + 'ER');
      inflected.add(w + 'ERS');
      inflected.add(w + 'EST');
      inflected.add(w + 'LY');
    }
  }

  return inflected;
}

// Build comprehensive valid word sets and clean target pools for lengths 5..8
export const validWordSets: Record<number, Set<string>> = {
  5: new Set<string>(),
  6: new Set<string>(),
  7: new Set<string>(),
  8: new Set<string>(),
};

export const targetPool: Record<number, string[]> = {
  5: [],
  6: [],
  7: [],
  8: [],
};

const exceptionsEndingInS = new Set([
  'GLASS', 'CLASS', 'GRASS', 'BRASS', 'CROSS', 'DRESS', 'PRESS', 'GUESS',
  'BLESS', 'CHESS', 'CHAOS', 'FOCUS', 'BONUS', 'VIRUS', 'LOCUS', 'LOTUS',
  'MINUS', 'NEXUS', 'SINUS', 'STATUS', 'CACTUS', 'CAMPUS', 'CIRCUS',
  'CITRUS', 'CHORUS', 'GENIUS', 'RADIUS', 'SERIES', 'SPECIES', 'STRESS',
  'ACCESS', 'EXCESS', 'PROCESS', 'SUCCESS', 'ADDRESS', 'EXPRESS', 'WITNESS',
  'FITNESS', 'ILLNESS', 'SADNESS', 'MADNESS', 'DARKNESS', 'WEAKNESS',
  'BUSINESS', 'KINDNESS', 'PROGRESS', 'CONGRESS', 'PRINCESS', 'COUNTESS',
  'WAITRESS', 'FORTRESS', 'MATTRESS', 'MISTRESS', 'DISTRESSS', 'COMPASS',
  'BIOMASS', 'CARCASS', 'HARNESS', ' SICKNESS', 'RICHNESS', 'HARDNESS',
  'SOFTNESS', 'FAIRNESS', 'GOODNESS', 'BOLDNESS', 'COLDNESS', 'WILDNESS'
]);

const excludedTargetProperNouns = new Set([
  'BERLIN', 'GERMAN', 'FRENCH', 'LONDON', 'EUROPE', 'SOVIET', 'OXFORD',
  'AUGUST', 'JERSEY', 'CHARLIE', 'RALPH', 'CHINA', 'WELSH', 'ROMAN',
  'LATIN', 'ASIAN', 'TEXAS', 'PARIS', 'TOKYO', 'INDIA', 'SPAIN', 'ITALY'
]);

// 1. Collect all base words across the project's dictionaries
const allRootWords = new Set<string>();

// Add Crowdle curated words first
([5, 6, 7, 8] as const).forEach((len) => {
  for (const raw of BASE_CROWDLE_WORDS[len]) {
    const clean = sanitizeWord(raw);
    if (clean.length === len && !EXCLUDED_TYPO_WORDS.has(clean)) {
      allRootWords.add(clean);
    }
  }
});

// Add extra valid words
for (const raw of EXTRA_VALID_WORDS) {
  const clean = sanitizeWord(raw);
  if (clean.length >= 3 && clean.length <= 8 && !EXCLUDED_TYPO_WORDS.has(clean)) {
    allRootWords.add(clean);
  }
}

// Add Unolingo curated word banks (3-6 letters)
for (const list of [WORDS_3, WORDS_4, WORDS_5, WORDS_6]) {
  for (const raw of list) {
    const clean = sanitizeWord(raw);
    if (clean.length >= 3 && clean.length <= 8 && !EXCLUDED_TYPO_WORDS.has(clean)) {
      allRootWords.add(clean);
    }
  }
}

// Add Squared core dictionary
for (const raw of CORE_DICTIONARY) {
  const clean = sanitizeWord(raw);
  if (clean.length >= 3 && clean.length <= 8 && !EXCLUDED_TYPO_WORDS.has(clean)) {
    allRootWords.add(clean);
  }
}

// Add Lexi dictionary (11,000+ words)
for (const raw of lexiDictionary as string[]) {
  const clean = sanitizeWord(raw);
  if (clean.length >= 3 && clean.length <= 8 && !EXCLUDED_TYPO_WORDS.has(clean)) {
    allRootWords.add(clean);
  }
}

// 2. Populate validWordSets with all root words + their valid 5-8 letter inflections
const allValidWordsWithInflections = generateInflections(allRootWords);
for (const word of allValidWordsWithInflections) {
  if (word.length >= 5 && word.length <= 8 && !EXCLUDED_TYPO_WORDS.has(word)) {
    validWordSets[word.length].add(word);
  }
}

// 3. Build clean targetPool (using curated words + Lexi + Unolingo + Squared root words, excluding regular plurals & proper nouns)
const targetCandidateSets: Record<number, Set<string>> = {
  5: new Set<string>(),
  6: new Set<string>(),
  7: new Set<string>(),
  8: new Set<string>(),
};

for (const word of allRootWords) {
  const len = word.length;
  if (len < 5 || len > 8) continue;
  if (EXCLUDED_TYPO_WORDS.has(word)) continue;
  if (excludedTargetProperNouns.has(word)) continue;
  if (!hasVowel(word)) continue;

  // Exclude regular plural/3rd-person -S words from being chosen as the secret target unless in exceptions
  if (word.endsWith('S') && !word.endsWith('SS') && !word.endsWith('US') && !word.endsWith('IS') && !exceptionsEndingInS.has(word)) {
    continue;
  }

  targetCandidateSets[len].add(word);
}

export const dictionary: Record<number, string[]> = {
  5: Array.from(validWordSets[5]).sort(),
  6: Array.from(validWordSets[6]).sort(),
  7: Array.from(validWordSets[7]).sort(),
  8: Array.from(validWordSets[8]).sort(),
};

([5, 6, 7, 8] as const).forEach((len) => {
  targetPool[len] = Array.from(targetCandidateSets[len]);
});

export type LetterStatus = 'correct' | 'present' | 'absent';

export interface EvaluatedLetter {
  letter: string;
  status: LetterStatus;
}

export function isValidCrowdleWord(word: string, length: number): boolean {
  const clean = word.trim().toUpperCase();
  if (clean.length !== length) return false;
  return validWordSets[length]?.has(clean) ?? false;
}

export function pickTargetWord(length: number, excludeWord?: string | null): string {
  const pool = targetPool[length] && targetPool[length].length > 0
    ? targetPool[length]
    : dictionary[length];
  if (!pool || pool.length === 0) return 'APPLE';
  const filtered = excludeWord ? pool.filter(w => w !== excludeWord) : pool;
  const source = filtered.length > 0 ? filtered : pool;
  return source[Math.floor(Math.random() * source.length)];
}

export function evaluateCrowdleGuess(guess: string, target: string): EvaluatedLetter[] {
  const g = guess.toUpperCase().split('');
  const t = target.toUpperCase().split('');
  const len = t.length;

  const result: EvaluatedLetter[] = g.map((letter) => ({
    letter,
    status: 'absent',
  }));

  const targetLetterCounts: Record<string, number> = {};

  // First pass: mark exact green matches
  for (let i = 0; i < len; i++) {
    if (g[i] === t[i]) {
      result[i].status = 'correct';
    } else {
      targetLetterCounts[t[i]] = (targetLetterCounts[t[i]] || 0) + 1;
    }
  }

  // Second pass: mark yellow present matches using remaining counts
  for (let i = 0; i < len; i++) {
    if (result[i].status === 'correct') continue;
    const letter = g[i];
    if (targetLetterCounts[letter] && targetLetterCounts[letter] > 0) {
      result[i].status = 'present';
      targetLetterCounts[letter]--;
    }
  }

  return result;
}
